-- THE PIQUINS: importar 218 productos originales sin borrar nada.
-- Ejecutar DESPUES de migracion/01_configurar_piquins.sql.
-- La columna imagen conserva exactamente el nombre del archivo en GitHub.
-- Esta carga NO modifica productos existentes, administradores, ni otros negocios.
-- Los productos importados quedan visibles; el panel podra ocultarlos despues.

on conflict (codigo) do nothing;

select categoria, count(*) as productos
from public.piquins_productos
group by categoria
order by categoria;
